namespace Flint;

final class Client {
    private Runtime $runtime;
    public readonly ApiResource $api;
    public function __construct(ClientOptions $options) {
        $this->runtime = new Runtime(SchemaRegistry::contract(), $options, true);
        $this->api = new ApiResource($this->runtime);
    }
    public function close(): void { $this->runtime->close(); }
